je_indian_famines = {
	icon = "gfx/interface/icons/event_icons/event_skull.dds"

	group = je_group_british_india
	dlc = dlc011

	activation_description = {
		always = yes
	}

	scripted_button = je_indian_famines_button_relief_kitchens
	scripted_button = je_indian_famines_button_work_camps
	scripted_button = je_indian_famines_button_epidemic_control

	is_shown_when_inactive = {
		has_dlc_feature = ip2_content
	    any_scope_state = {
			is_in_geographic_region = geographic_region_india
	    }
	}

	possible = {
		OR = {
			any_scope_state = {
				region = sr:region_north_india
				has_famine = yes
				count >= 4
			}
			any_scope_state = {
				region = sr:region_south_india
				has_famine = yes
				count >= 4
			}
			any_scope_state = {
				is_in_geographic_region = geographic_region_india
				has_famine = yes
				count >= 15
			}
		}
		custom_tooltip = {
			text = indian_famine_cooldown_tt
		    NOT = {
		    	has_variable = indian_famine_je_cooldown_var
		    }
		}
	}

	immediate = {
		add_modifier = {
			name = india_famine_radicals_modifier
			days = very_long_modifier_time
		}
		if = {
			limit = {
				any_scope_state = {
					is_in_geographic_region = geographic_region_india
					has_famine = yes
					count >= 15
				}
			}
			set_variable = great_indian_famine_var
		}
		else_if = {
			limit = {
				any_scope_state = {
					region = sr:region_north_india
					has_famine = yes
					count >= 5
				}
				NOT = {
					any_scope_state = {
						is_in_geographic_region = geographic_region_india
						has_famine = yes
						count >= 15
					}
				}
			}
			set_variable = bengal_famine_var
		}
		else_if = {
			limit = {
				any_scope_state = {
					region = sr:region_north_india
					has_famine = yes
					count >= 4
				}
				NOT = {
					any_scope_state = {
						is_in_geographic_region = geographic_region_india
						has_famine = yes
						count >= 15
					}
				}
			}
			set_variable = punjab_famine_var
		}
		else_if = {
			limit = {
				any_scope_state = {
					region = sr:region_south_india
					has_famine = yes
					count >= 4
				}
				NOT = {
					any_scope_state = {
						is_in_geographic_region = geographic_region_india
						has_famine = yes
						count >= 15
					}
				}
			}
			set_variable = bombay_famine_var
		}
		else_if = {
			limit = {
				any_scope_state = {
					region = sr:region_south_india
					has_famine = yes
					count >= 5
				}
				NOT = {
					any_scope_state = {
						is_in_geographic_region = geographic_region_india
						has_famine = yes
						count >= 15
					}
				}
			}
			set_variable = madras_famine_var
		}
		else_if = {
			limit = {
				any_scope_state = {
					region = sr:region_north_india
					has_famine = yes
					count >= 5
				}
				NOT = {
					any_scope_state = {
						is_in_geographic_region = geographic_region_india
						has_famine = yes
						count >= 15
					}
				}
			}
			set_variable = central_india_famine_var
		}
	}

	outcome = {
		header = je_standard_completion_header
		effect_header = je_standard_on_completion_header
		color = "gold_positive"
		conclusion_desc = je_standard_completion_conclusion_desc
		trigger = {
			trigger_if = {
				limit = {
					has_variable = bengal_famine_var
				}
				NOT = {
					any_scope_state = {
						is_in_geographic_region = geographic_region_bengal_old
						has_famine = yes
					}
				}
			}
			trigger_if = {
				limit = {
					has_variable = bombay_famine_var
				}
				NOT = {
					any_scope_state = {
						is_in_geographic_region = geographic_region_bombay_old
						has_famine = yes
					}
				}
			}
			trigger_if = {
				limit = {
					has_variable = madras_famine_var
				}
				NOT = {
					any_scope_state = {
						is_in_geographic_region = geographic_region_madras_old
						has_famine = yes
					}
				}
			}
			trigger_if = {
				limit = {
					has_variable = punjab_famine_var
				}
				NOT = {
					any_scope_state = {
						is_in_geographic_region = geographic_region_punjab_old
						has_famine = yes
					}
				}
			}
			trigger_if = {
				limit = {
					has_variable = central_india_famine_var
				}
				NOT = {
					any_scope_state = {
						is_in_geographic_region = geographic_region_central_india_old
						has_famine = yes
					}
				}
			}
			trigger_if = {
				limit = {
					has_variable = great_indian_famine_var
				}
				NOT = {
					any_scope_state = {
						is_in_geographic_region = geographic_region_india
						has_famine = yes
					}
				}
			}
		}
		effect = {
			custom_tooltip = je_indian_famines_completion_tt
			remove_modifier = india_famine_radicals_modifier
			set_variable = {
				name = indian_famine_je_cooldown_var
				days = normal_modifier_time
			}
			je_indian_famines_cleanup = yes
		}
	}

	on_yearly_pulse = {
		random_events = {
			20 = 0
			5 = indian_famines.1
			5 = indian_famines.2
			5 = indian_famines.4
		}
		# Negatively affects the progress bars of the Home Rule and Sepoy Mutiny JEs while active
	}
	weight = 200


	should_be_pinned_by_default_uninvolved_or_context = yes

	transferable = no
}

