							}
						}
						{
							article = state_transfer
							source_country = scope:bolivia_border_treaty_country_scope
							target_country = ROOT
							inputs = {
								{ state = scope:ceded_mato_grosso_scope }
							}
						}
						{
							article = money_transfer
							source_country = ROOT
							target_country = scope:bolivia_border_treaty_country_scope
							inputs = {
								{ quantity = 1000 }
							}
						}
					}
				}
			}
		}
		else = {
			custom_tooltip = {
				text = treaty_of_ayacucho_tt
				create_treaty = {
					name = treaty_name_treaty_of_ayacucho
					first_country = ROOT
					second_country = scope:bolivia_border_treaty_country_scope
					is_draft = no
					binding_period = { years = 5 }

					articles_to_create = {
						{
							article = state_transfer
							source_country = scope:bolivia_border_treaty_country_scope
							target_country = ROOT
							inputs = {
								{ state = scope:ceded_amazonas_scope }
							}
						}
						{
							article = money_transfer
							source_country = ROOT
							target_country = scope:bolivia_border_treaty_country_scope
							inputs = {
								{ quantity = 1000 }
							}
						}
